#!/usr/bin/env node
/**
 * Post-analyze hook — runs after `node .gitnexus/run.cjs analyze`.
 *
 * Responsibility: restore CLAUDE.md → AGENTS.md hardlink.
 *
 * GitNexus analyze writes both files independently, breaking the NTFS
 * hardlink. On Windows the two files share one inode only when linked
 * via `linkSync(agentsPath, claudePath)`; otherwise Claude Code and
 * every other editor see two divergent sources. This hook detects and
 * rebuilds the hardlink after every analyze run.
 *
 * Why a separate hook (not inside .gitnexus/run.cjs):
 *   - .gitnexus/run.cjs is auto-regenerated by `gitnexus analyze` and
 *     must stay byte-identical to the upstream template
 *     (resolve-invocation.test.ts enforces this). Hooking there would
 *     break the contract.
 *   - `bun run analyze` (package.json script) is the user-facing wrapper
 *     that invokes both. README / AGENTS.md instructions point to it.
 *
 * Idempotent: safe to run multiple times in a row.
 *
 * @see https://github.com/abhigyanpatwari/GitNexus/blob/main/gitnexus/src/cli/ai-context.ts
 *      (the `<!-- gitnexus:keep -->` marker behavior this script leans on)
 */
import { existsSync, linkSync, statSync, unlinkSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(__dirname, '..', '..'); // nexus/scripts → nexus/ → repo root
const agentsPath = join(repoRoot, 'AGENTS.md');
const claudePath = join(repoRoot, 'CLAUDE.md');

/** True iff the two paths point to the same inode (NTFS hardlink or symlink). */
function isSameInode(a, b) {
  try {
    return statSync(a).ino === statSync(b).ino;
  } catch {
    return false;
  }
}

/**
 * Restore CLAUDE.md as a hardlink to AGENTS.md.
 * Idempotent: if already a hardlink, no-op.
 * Tolerates CLAUDE.md missing (e.g. fresh clone after first analyze).
 */
function restoreHardlink() {
  if (!existsSync(agentsPath)) {
    console.warn('[postanalyze] AGENTS.md missing — skipping hardlink restore');
    return false;
  }

  // Both files present and already linked → nothing to do
  if (existsSync(claudePath) && isSameInode(agentsPath, claudePath)) {
    return true;
  }

  // GitNexus analyze wrote CLAUDE.md as a separate file → unlink + relink
  if (existsSync(claudePath)) {
    unlinkSync(claudePath);
  }
  linkSync(agentsPath, claudePath);
  console.log('[postanalyze] Restored CLAUDE.md → AGENTS.md hardlink');
  return true;
}

// --- main ---
let exitCode = 0;
try {
  restoreHardlink();
} catch (err) {
  console.error(`[postanalyze] Hardlink restore failed: ${err.message}`);
  exitCode = 1;
}

process.exit(exitCode);
